static void check_impl(int ok,const char *expr,int line){if(!ok){fprintf(stderr,"%s:%d: check failed: %s\n",__FILE__,line,expr);exit(EXIT_FAILURE);}}
#define CHECK(x) check_impl((x),#x,__LINE__)
static int close_float(float a,float b){float d=a-b;if(d<0)d=-d;return d<0.01f;}

static void compile_surface(void)
{
    quantapdf_form *form=NULL;quantapdf_form_field_type type=QUANTAPDF_FORM_FIELD_UNKNOWN;quantapdf_form_value_presence presence=QUANTAPDF_FORM_VALUE_NOT_APPLICABLE;
    quantapdf_form_value_kind vk=QUANTAPDF_FORM_VALUE_UTF8;quantapdf_form_option_kind ok=QUANTAPDF_FORM_OPTION_BUTTON_STATE;quantapdf_form_field_info fi={0};
    quantapdf_form_value_info vi={0};quantapdf_form_option_info oi={0};quantapdf_form_widget_info wi={0};quantapdf_document *d=NULL;const char *s=NULL;size_t n=0,c=0;
    (void)type;(void)presence;(void)vk;(void)ok;
    if(0){(void)quantapdf_document_form(d,&form);(void)quantapdf_form_field_count(form,&c);(void)quantapdf_form_field_get_info(form,0,&fi);(void)quantapdf_form_field_name(form,0,&s,&n);(void)quantapdf_form_field_label(form,0,&s,&n);(void)quantapdf_form_field_value_get_info(form,0,0,&vi);(void)quantapdf_form_field_value_utf8(form,0,0,&s,&n);(void)quantapdf_form_field_option_get_info(form,0,0,&oi);(void)quantapdf_form_field_option_export(form,0,0,&s,&n);(void)quantapdf_form_field_option_display(form,0,0,&s,&n);(void)quantapdf_form_widget_count(form,&c);(void)quantapdf_form_widget_get_info(form,0,&wi);quantapdf_drop_form(form);}
}

static void expect_empty(const char *path){quantapdf_document *d=NULL;quantapdf_form *f=NULL;size_t a=99,b=99;CHECK(quantapdf_open(test_context(), path,NULL,&d)==QUANTAPDF_OK);CHECK(quantapdf_document_form(d,&f)==QUANTAPDF_OK);CHECK(f!=NULL);quantapdf_close(d);CHECK(quantapdf_form_field_count(f,&a)==QUANTAPDF_OK);CHECK(a==0);CHECK(quantapdf_form_widget_count(f,&b)==QUANTAPDF_OK);CHECK(b==0);quantapdf_drop_form(f);}
static void expect_string(const quantapdf_form *f,size_t i,int label,const char *e,int present){const char *s=(const char *)(uintptr_t)1;size_t n=99;quantapdf_status st=label?quantapdf_form_field_label(f,i,&s,&n):quantapdf_form_field_name(f,i,&s,&n);CHECK(st==QUANTAPDF_OK);if(!present){CHECK(s==NULL);CHECK(n==0);return;}CHECK(s!=NULL);CHECK(n==strlen(e));CHECK(memcmp(s,e,n)==0);CHECK(s[n]=='\0');}
static void expect_extract_status(const char *path,quantapdf_status expected){int sentinel=0;quantapdf_document *d=NULL;quantapdf_form *f=(quantapdf_form *)&sentinel;CHECK(quantapdf_open(test_context(), path,NULL,&d)==QUANTAPDF_OK);CHECK(quantapdf_document_form(d,&f)==expected);CHECK(f==NULL);quantapdf_close(d);}

static void test_api_shell(void){int sentinel=0;quantapdf_form *f=(quantapdf_form *)&sentinel;size_t c=99;const char *s=(const char *)&sentinel;size_t n=99;CHECK(QUANTAPDF_FORM_FIELD_UNKNOWN==0);CHECK(QUANTAPDF_FORM_FIELD_SIGNATURE==7);CHECK(QUANTAPDF_FORM_VALUE_NOT_APPLICABLE==0);CHECK(QUANTAPDF_FORM_VALUE_PRESENT==2);CHECK(QUANTAPDF_FORM_VALUE_UTF8==1);CHECK(QUANTAPDF_FORM_VALUE_OPTION==2);CHECK(QUANTAPDF_FORM_OPTION_BUTTON_STATE==1);CHECK(QUANTAPDF_FORM_OPTION_CHOICE==2);CHECK(quantapdf_document_form(NULL,&f)==QUANTAPDF_ERROR_ARGUMENT);CHECK(f==NULL);CHECK(quantapdf_document_form(NULL,NULL)==QUANTAPDF_ERROR_ARGUMENT);CHECK(quantapdf_form_field_count(NULL,&c)==QUANTAPDF_ERROR_ARGUMENT);CHECK(c==0);CHECK(quantapdf_form_widget_count(NULL,&c)==QUANTAPDF_ERROR_ARGUMENT);CHECK(c==0);CHECK(quantapdf_form_field_name(NULL,0,&s,&n)==QUANTAPDF_ERROR_ARGUMENT);CHECK(s==NULL&&n==0);quantapdf_drop_form(NULL);}
static void test_empty_and_non_pdf(void){quantapdf_document *d=NULL;expect_empty(NO_ACROFORM_PDF);expect_empty(ACROFORM_NO_FIELDS_PDF);expect_empty(ACROFORM_EMPTY_FIELDS_PDF);CHECK(quantapdf_open(test_context(), NON_PDF,NULL,&d)==QUANTAPDF_ERROR_FORMAT);CHECK(d==NULL);}

