static void test_structure(void){quantapdf_document *d=NULL;quantapdf_form *f=NULL;size_t c=99;CHECK(quantapdf_open(test_context(), ACROFORM_STRUCTURE_PDF,NULL,&d)==QUANTAPDF_OK);CHECK(quantapdf_document_form(d,&f)==QUANTAPDF_OK);CHECK(quantapdf_form_field_count(f,&c)==QUANTAPDF_OK);CHECK(c==4);CHECK(quantapdf_form_widget_count(f,&c)==QUANTAPDF_OK);CHECK(c==0);expect_structure_info(f,0);expect_string(f,0,0,"profile.nickname",1);expect_string(f,0,1,"Profile label",1);expect_structure_info(f,1);expect_string(f,1,0,"repeat",1);expect_string(f,1,1,"",0);expect_structure_info(f,2);expect_string(f,2,0,"",0);expect_structure_info(f,3);expect_string(f,3,0,"",1);quantapdf_drop_form(f);quantapdf_close(d);expect_extract_status(ACROFORM_BAD_ROOT_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_BAD_FIELDS_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_BAD_KID_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_CYCLE_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_REPEATED_NODE_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_PARENT_MISMATCH_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_ROOT_PARENT_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_DEPTH_257_PDF,QUANTAPDF_ERROR_UNSUPPORTED);expect_extract_status(ACROFORM_MIXED_GROUP_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_GROUP_CONFLICT_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_DUPLICATE_NAME_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_PERIOD_NAME_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_BAD_FT_PDF,QUANTAPDF_ERROR_FORMAT);expect_extract_status(ACROFORM_BAD_FF_PDF,QUANTAPDF_ERROR_FORMAT);}

static void expect_widget_field(const quantapdf_form *f,size_t i,quantapdf_form_field_type t,quantapdf_form_value_presence p,size_t o,size_t w){quantapdf_form_field_info x={0};CHECK(quantapdf_form_field_get_info(f,i,&x)==QUANTAPDF_OK);CHECK(x.type==t);CHECK(x.value_presence==p);CHECK(x.value_count==0);CHECK(x.option_count==o);CHECK(x.widget_count==w);}
